// The road journeys generated by local air passengers. Rates follow each flight's passenger load
// and its hall. Pickup traffic starts after the aircraft actually reaches its stand.
import type { Stand } from '../../shared/layout.ts';
import { NOT_YET, type FlightBook } from '../airside/flights.ts';
import { CONFIG } from '../config.ts';
import { AIRLINE_BY_CODE } from '../fleet.ts';
import type { Rng } from '../rng.ts';
import { arrivalStart, holdroomForStand, type PassengerHalls } from '../terminal/passenger-halls.ts';
import type { Link, RoadNet } from './net.ts';

type Direction = 'dropOff' | 'pickUp';
type Location = { x: number; y: number };
type Timing = readonly [number, number, number];
type Frontage = { index: number; share: number }[];
const settings = CONFIG.curbTraffic;

/** Fraction of a triangular arrival wave on the roads by the given elapsed time in minutes. */
function fraction(t: number, [first, peak, last]: Timing): number {
  if (t <= first) return 0;
  if (t >= last) return 1;
  if (t <= peak) return (t - first) ** 2 / ((last - first) * (peak - first));
  return 1 - (last - t) ** 2 / ((last - first) * (last - peak));
}

/** Spread vehicles over the nearby curb segments in proportion to their available frontage. */
function frontage(at: Location, links: readonly Link[], positions: Location[]): Frontage {
  const distances = positions.map((p) => Math.hypot(p.x - at.x, p.y - at.y));
  const limit = Math.min(...distances) + settings.frontageSpread;
  const eligible = distances.flatMap((d, index) => d <= limit ? [{ index, share: links[index].len }] : []);
  const length = eligible.reduce((sum, l) => sum + l.share, 0);
  for (const l of eligible) l.share /= length;
  return eligible;
}

export class FlightCurbDemand {
  readonly perHour = { dropOff: 0, pickUp: 0 };
  private readonly book: FlightBook;
  private readonly links: Record<Direction, readonly Link[]>;
  private readonly weights: Record<Direction, number[]>;
  private readonly byStand = new Map<string, { departures: Frontage; domestic: Frontage; international: Frontage }>();
  private minute = -Infinity;

  constructor(book: FlightBook, stands: readonly Stand[], net: RoadNet, departures: readonly Link[], arrivals: readonly Link[], plan: PassengerHalls) {
    this.book = book;
    this.links = { dropOff: departures, pickUp: arrivals };
    this.weights = { dropOff: new Array<number>(departures.length).fill(0), pickUp: new Array<number>(arrivals.length).fill(0) };
    const midpoints = (links: readonly Link[]): Location[] => links.map((l) => net.point(l, l.len / 2, 0, { x: 0, y: 0, z: 0, heading: 0 }));
    const upper = midpoints(departures);
    const lower = midpoints(arrivals);
    for (const stand of stands) {
      // Remote stands bus to the nearest holdroom, just as the people simulation does.
      const holdroom = holdroomForStand(plan, stand);
      if (!holdroom) continue;
      const area = holdroom.area;
      const hall = plan.checkpoint.get(area) ?? holdroom;
      const customsArea = arrivalStart(plan, holdroom, true).area;
      const domestic = plan.claim.get(area)?.domestic ?? hall;
      const international = plan.claim.get(customsArea)?.international ?? plan.checkpoint.get(customsArea) ?? hall;
      this.byStand.set(stand.id, {
        departures: frontage(hall, departures, upper),
        domestic: frontage(domestic, arrivals, lower),
        international: frontage(international, arrivals, lower),
      });
    }
  }

  update(now: number): void {
    const minute = Math.floor(now / 60);
    if (minute === this.minute) return;
    this.minute = minute;
    this.perHour.dropOff = this.perHour.pickUp = 0;
    this.weights.dropOff.fill(0);
    this.weights.pickUp.fill(0);
    for (const visit of this.book.visits.values()) {
      const r = visit.rotation;
      const lead = visit.std / 60 - minute;
      // A flight marked done at startup had already departed before any aircraft were simulated.
      const parked = visit.onBlockAt === NOT_YET && visit.state === 'done' ? visit.sta : visit.onBlockAt;
      const since = minute - parked / 60;
      const departure = r.internationalOut ? settings.internationalDeparture : settings.domesticDeparture;
      const arrival = r.customs ? settings.customsArrival : settings.domesticArrival;
      const out = lead > departure[0] && lead - 1 < departure[2] && !visit.doorsClosed && visit.state !== 'done';
      const into = since + 1 > arrival[0] && since < arrival[2];
      if (!out && !into) continue;
      const curb = this.byStand.get(visit.stand);
      if (!curb) continue;
      const local = 1 - (AIRLINE_BY_CODE[r.airline]?.connecting ?? 0);
      const vehiclesPerHour = 60 * settings.tripsPerPassenger;
      if (out) this.add('dropOff', curb.departures, r.paxOut * local * vehiclesPerHour * (fraction(lead, departure) - fraction(lead - 1, departure)));
      if (into) this.add('pickUp', r.customs ? curb.international : curb.domestic, r.paxIn * (r.customs ? 1 : local) * vehiclesPerHour * (fraction(since + 1, arrival) - fraction(since, arrival)));
    }
  }

  private add(direction: Direction, curb: Frontage, perHour: number): void {
    if (!curb.length) return;
    this.perHour[direction] += perHour;
    for (const { index, share } of curb) this.weights[direction][index] += perHour * share;
  }

  pick(direction: Direction, rng: Rng): Link {
    return this.links[direction][rng.weightedIndex(this.weights[direction])];
  }
}
